// Get CrowdStrike OAuth2 Token
const clientId = 'YOUR_CLIENT_ID_HERE';
const clientSecret = 'YOUR_CLIENT_SECRET_HERE';

const response = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://api.us-2.crowdstrike.com/oauth2/token',
  headers: {
    'Content-Type': 'application/x-www-form-urlencoded',
  },
  body: `client_id=${clientId}&client_secret=${clientSecret}`,
  returnFullResponse: true
});

return [{
  json: {
    access_token: response.body.access_token,
    expires_in: response.body.expires_in
  }
}];

// Calculate time filter for last 2 minutes
const now = new Date();
const twoMinutesAgo = new Date(now.getTime() - 2 * 60 * 1000);
const filterTime = twoMinutesAgo.toISOString();

return [{
  json: {
    access_token: $input.first().json.access_token,
    filter_time: filterTime
  }
}];

// Check if we have any detections
const response = $input.first().json;
const resources = response.resources || [];

if (resources.length === 0) {
  // No new detections, stop workflow
  return [];
}

// Get the token from earlier node
const tokenNode = $('Prepare Query').first();
const accessToken = tokenNode.json.access_token;

return [{
  json: {
    detection_ids: resources,
    access_token: accessToken
  }
}];

// Split detections and extract agent_ids for device lookup
const response = $input.first().json;
const detections = response.resources || [];

// Get the token
const tokenNode = $('Check for Detections').first();
const accessToken = tokenNode.json.access_token;

// Extract unique agent_ids
const agentIds = [...new Set(detections.map(d => d.agent_id).filter(id => id))];

return [{
  json: {
    detections: detections,
    agent_ids: agentIds,
    access_token: accessToken
  }
}];

// Merge device details with detections
const deviceResponse = $input.first().json;
const devices = deviceResponse.resources || [];

// Get detections from earlier node
const extractNode = $('Extract Agent IDs').first();
const detections = extractNode.json.detections || [];

// Create device lookup map
const deviceMap = {};
for (const device of devices) {
  deviceMap[device.device_id] = device;
}

// Merge device info into each detection
const enrichedDetections = detections.map(detection => {
  const device = deviceMap[detection.agent_id] || {};
  return {
    ...detection,
    device_info: device
  };
});

// Return each detection as separate item
return enrichedDetections.map(detection => ({
  json: detection
}));

// Format CrowdStrike Alert with Device Info for the security alert webhook
const alert = $input.first().json;
const device = alert.device_info || {};
const incident = alert.incident || {};

// Calculate severity from incident score
const score = parseFloat(incident.highest_score) || 0;
let severityName = 'info';
if (score >= 4) severityName = 'critical';
else if (score >= 3) severityName = 'high';
else if (score >= 2) severityName = 'medium';
else if (score >= 1) severityName = 'low';

const payload = {
  metadata: {
    eventType: 'DetectionSummaryEvent',
    customerIDString: alert.cid || ''
  },
  event: {
    detection_id: alert.composite_id || alert.id || '',
    created_timestamp: alert.created_timestamp || '',
    severity: Math.round(score * 20),
    max_severity_displayname: severityName,
    confidence: 0,
    detect_name: alert.type === 'xdr' ? 'XDR Incident' : (alert.name || 'CrowdStrike Alert'),
    detect_description: 'CrowdStrike ' + (alert.type || 'alert').toUpperCase() + ' - Score: ' + score.toFixed(2),
    technique: alert.technique || '',
    tactic: alert.tactic || '',
    filepath: alert.filepath || '',
    sha256: alert.sha256 || '',
    cmdline: alert.cmdline || '',
    user_name: device.last_login_user || ''
  },
  device: {
    hostname: device.hostname || device.device_id || alert.agent_id || '',
    device_id: device.device_id || alert.agent_id || '',
    site_name: (device.groups && device.groups[0]) || '',
    groups: device.groups || [],
    local_ip: device.local_ip || '',
    external_ip: device.external_ip || '',
    os_version: device.os_version || alert.platform || '',
    platform_name: device.platform_name || alert.platform || '',
    machine_domain: device.machine_domain || '',
    system_manufacturer: device.system_manufacturer || '',
    system_product_name: device.system_product_name || ''
  },
  falcon_host_link: alert.falcon_host_link || ''
};

return [{ json: payload }];
